/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: status, active, clip, fileInput, uploadButton, mount
 *   Constants: trackId, token, uploadResult, messages
 * Tests
 *   - renders nothing while the feature is disabled or for an Audio MediaTrack
 *   - uploads a chosen clip as one bounded multipart request bound to the current source and revision
 *   - Upload stays disabled until a clip is chosen
 *   - Remove and Reconcile failures name the cause without blaming a file
 *   - a change that commits but leaves old storage reports the pending cleanup
 *   - an .mp4 that the system reports with no type is still sent, since the server checks its bytes
 *   - controls stay disabled until the status refetch after an upload lands
 *   - an outdated preview is explained, and Remove sends the current revision
 *   - unfinished work offers Reconcile and blocks upload while a live lease protects it
 *   - a preview made for an earlier Video offers Reconcile, which retires it
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { cleanup, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { deferred, json, session, viewer } from './adminFixtures.testSupport';
import { MotionPreviewPanel } from './MotionPreviewPanel';

const trackId = '111111111111111111111111';
const token = 'f'.repeat(32);
const status = (overrides: Record<string, unknown> = {}) => ({
  eligible: true, sourceToken: token, revision: 2, active: null, pending: null, cleanup: null, ...overrides
});
const active = (current = true) => ({
  revision: `pv_${'1'.repeat(32)}`, byteLength: 900000, durationMs: 6400, width: 854, height: 480,
  current, updatedAt: '2026-10-18T00:00:00.000Z'
});
const uploadResult = { revision: `pv_${'1'.repeat(32)}`, durationMs: 6400, width: 854, height: 480, byteLength: 900000, cleanupPending: false };
const clip = (bytes = 3, type = 'video/mp4', name = 'clip.mp4') => new File([new Uint8Array(bytes)], name, { type });
const fileInput = () => screen.getByLabelText('Preview clip (MP4)') as HTMLInputElement;
const uploadButton = () => screen.getByRole('button', { name: 'Upload preview' });

const messages = {
  file: 'This clip was not accepted. Upload a muted MP4 with 8-bit H.264 video (Baseline, Main, or High), at most 8.5 seconds, 854 × 480, and 4 MiB.',
  changed: 'The preview or Video changed in another session. This panel now shows the latest state; try again.',
  busy: 'Another preview operation is still running. Try again shortly.',
  reconcile: 'Unfinished preview work needs attention first. Use Reconcile, then try again.',
  generic: 'The preview change could not be completed. Try again.'
};

const mount = () => {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  return render(<QueryClientProvider client={client}><MotionPreviewPanel id={trackId} /></QueryClientProvider>);
};

beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); });

test('renders nothing while the feature is disabled or for an Audio MediaTrack', async () => {
  const fetchMock = vi.fn(async () => json({ code: 'ADMIN_MOTION_PREVIEW_DISABLED' }, 404));
  vi.stubGlobal('fetch', fetchMock);
  const disabled = mount();
  await waitFor(() => expect(fetchMock).toHaveBeenCalled());
  await waitFor(() => expect(disabled.container).toBeEmptyDOMElement());
  disabled.unmount();

  vi.stubGlobal('fetch', vi.fn(async () => json(status({ eligible: false, sourceToken: null }))));
  const audio = mount();
  await waitFor(() => expect(audio.container).toBeEmptyDOMElement());
});

test('uploads a chosen clip as one bounded multipart request bound to the current source and revision', async () => {
  const user = userEvent.setup();
  const requests: Array<{ url: string; init?: RequestInit }> = [];
  let uploaded = false;
  vi.stubGlobal('fetch', vi.fn(async (url: string, init?: RequestInit) => {
    requests.push({ url, init });
    if (init?.method === 'POST') {
      uploaded = true;
      return json(uploadResult, 201);
    }
    return json(status(uploaded ? { revision: 6, active: active() } : {}));
  }));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  await user.upload(fileInput(), clip());
  await user.click(uploadButton());

  expect(await screen.findByText('The preview was uploaded.')).toBeInTheDocument();
  expect(await screen.findByText('Current preview: 6.4 s, 854 × 480.')).toBeInTheDocument();
  // Success clears the choice, so the same clip is not uploaded twice by accident.
  expect(fileInput().files).toHaveLength(0);
  expect(uploadButton()).toBeDisabled();
  const post = requests.find((request) => request.init?.method === 'POST')!;
  expect(post.url).toBe(`/api/admin/v1/catalog/audioTrack/${trackId}/motion-preview`);
  const contentType = new Headers(post.init!.headers).get('Content-Type')!;
  expect(contentType).toMatch(/^multipart\/form-data; boundary=FinitudeMotionPreview-/);
  // JSDOM's Blob has no text(); FileReader reads the exact multipart envelope.
  const body = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.readAsText(post.init!.body as Blob);
  });
  expect(body).toContain(`name="sourceToken"\r\n\r\n${token}\r\n`);
  expect(body).toContain('name="expectedRevision"\r\n\r\n2\r\n');
  expect(body).toContain('name="motionPreviewFile"; filename="preview.mp4"\r\nContent-Type: video/mp4');
});

test('Upload stays disabled until a clip is chosen', async () => {
  const user = userEvent.setup();
  vi.stubGlobal('fetch', vi.fn(async () => json(status())));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  expect(uploadButton()).toBeDisabled();
  await user.upload(fileInput(), clip());
  expect(uploadButton()).toBeEnabled();
});

test.each([
  ['a rejected file', 400, { code: 'ADMIN_MOTION_PREVIEW_INVALID' }, messages.file],
  ['a request over the size gate', 413, { message: 'Upload request exceeds the 5 MB limit.' }, messages.file],
  ['a stale revision', 409, { code: 'ADMIN_MOTION_PREVIEW_STALE_REVISION' }, messages.changed],
  ['a changed Video', 409, { code: 'ADMIN_MOTION_PREVIEW_SOURCE_CHANGED' }, messages.changed],
  ['a busy preview', 409, { code: 'ADMIN_MOTION_PREVIEW_BUSY' }, messages.busy],
  ['pending cleanup', 409, { code: 'ADMIN_MOTION_PREVIEW_CLEANUP_PENDING' }, messages.busy],
  ['a full upload limiter', 429, { message: 'Too many concurrent requests.' }, messages.busy],
  ['required reconciliation', 503, { code: 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED' }, messages.reconcile],
  ['a storage failure', 502, { code: 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED' }, messages.generic]
])('an upload failed by %s explains it, refreshes the status, and keeps the chosen clip', async (_name, code, body, message) => {
  const user = userEvent.setup();
  let reads = 0;
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method === 'POST') return json(body, code);
    reads += 1;
    return json(status());
  }));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  await user.upload(fileInput(), clip());
  await user.click(uploadButton());

  expect(await screen.findByRole('alert')).toHaveTextContent(message);
  await waitFor(() => expect(reads).toBe(2));
  expect(fileInput().files?.[0]?.name).toBe('clip.mp4');
  await waitFor(() => expect(uploadButton()).toBeEnabled());
});

test('Remove and Reconcile failures name the cause without blaming a file', async () => {
  const user = userEvent.setup();
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method === 'DELETE') return json({ code: 'ADMIN_MOTION_PREVIEW_STALE_REVISION' }, 409);
    return json(status({ active: active() }));
  }));
  mount();
  await user.click(await screen.findByRole('button', { name: 'Remove preview' }));
  expect(await screen.findByRole('alert')).toHaveTextContent(messages.changed);
  cleanup();

  vi.stubGlobal('fetch', vi.fn(async (url: string) => {
    if (url.endsWith('/reconcile')) return json({ code: 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED' }, 502);
    return json(status({ cleanup: { status: 'deleteFailed', reason: 'replaced' } }));
  }));
  mount();
  await user.click(await screen.findByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByRole('alert')).toHaveTextContent(messages.generic);
  cleanup();

  vi.stubGlobal('fetch', vi.fn(async (url: string) => {
    if (url.endsWith('/reconcile')) throw new TypeError('Failed to fetch');
    return json(status({ cleanup: { status: 'pending', reason: 'removed' } }));
  }));
  mount();
  await user.click(await screen.findByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByRole('alert')).toHaveTextContent(messages.generic);
  cleanup();

  // Reconcile that cannot finish never tells the administrator to use Reconcile.
  vi.stubGlobal('fetch', vi.fn(async (url: string) => {
    if (url.endsWith('/reconcile')) return json({ code: 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED' }, 503);
    return json(status({ pending: { status: 'failed', outcomeUnknown: true, leaseActive: false } }));
  }));
  mount();
  await user.click(await screen.findByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByRole('alert')).toHaveTextContent(messages.generic);
});

test('a change that commits but leaves old storage reports the pending cleanup', async () => {
  const user = userEvent.setup();
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method === 'DELETE') return json({ cleanupPending: true });
    return json(status({ active: active() }));
  }));
  mount();
  await user.click(await screen.findByRole('button', { name: 'Remove preview' }));
  expect(await screen.findByText('Done, but an old preview file still needs cleanup. Reconcile later.')).toBeInTheDocument();
});

test('an .mp4 that the system reports with no type is still sent, since the server checks its bytes', async () => {
  const user = userEvent.setup({ applyAccept: false });
  const methods: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    methods.push(init?.method ?? 'GET');
    return init?.method === 'POST' ? json(uploadResult, 201) : json(status());
  }));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  await user.upload(fileInput(), clip(3, '', 'clip.MP4'));
  await user.click(uploadButton());
  expect(await screen.findByText('The preview was uploaded.')).toBeInTheDocument();
  expect(methods).toContain('POST');
});

test.each([
  ['an oversized clip', clip(4 * 1024 * 1024 + 1)],
  ['a clip that is not MP4', clip(3, 'video/quicktime', 'clip.mov')],
  ['an untyped file that is not named .mp4', clip(3, '', 'clip.mov')]
])('%s is refused on this device without sending a request', async (_name, chosen) => {
  // A browser lets the administrator override the picker's MP4 filter, so the panel must not rely on it.
  const user = userEvent.setup({ applyAccept: false });
  const methods: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    methods.push(init?.method ?? 'GET');
    return json(status());
  }));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  await user.upload(fileInput(), chosen);
  await user.click(uploadButton());

  expect(await screen.findByRole('alert')).toHaveTextContent(messages.file);
  expect(methods).toEqual(['GET']);
  expect(fileInput().files?.[0]).toBe(chosen);
});

test('controls stay disabled until the status refetch after an upload lands', async () => {
  const user = userEvent.setup();
  const refetch = deferred<Response>();
  const writes: RequestInit[] = [];
  let reads = 0;
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method === 'POST') return json(uploadResult, 201);
    if (init?.method === 'DELETE') { writes.push(init); return json({ cleanupPending: false }); }
    reads += 1;
    return reads === 1 ? json(status({ active: active() })) : refetch.promise;
  }));
  mount();

  expect(await screen.findByText('Current preview: 6.4 s, 854 × 480.')).toBeInTheDocument();
  await user.upload(fileInput(), clip());
  await user.click(uploadButton());

  expect(await screen.findByText('The preview was uploaded.')).toBeInTheDocument();
  await waitFor(() => expect(reads).toBe(2));
  expect(screen.getByRole('button', { name: 'Remove preview' })).toBeDisabled();
  expect(fileInput()).toBeDisabled();

  refetch.resolve(json(status({ revision: 6, active: active() })));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Remove preview' })).toBeEnabled());
  await user.click(screen.getByRole('button', { name: 'Remove preview' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(JSON.parse(String(writes[0].body))).toEqual({ expectedRevision: 6 });
});

test('an outdated preview is explained, and Remove sends the current revision', async () => {
  const user = userEvent.setup();
  const requests: RequestInit[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method) requests.push(init);
    return init?.method === 'DELETE' ? json({ cleanupPending: false }) : json(status({ active: active(false) }));
  }));
  mount();

  expect(await screen.findByText(/made for an earlier Video and stays hidden/)).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Remove preview' }));

  expect(await screen.findByText('The preview was removed.')).toBeInTheDocument();
  expect(requests[0].method).toBe('DELETE');
  expect(JSON.parse(String(requests[0].body))).toEqual({ expectedRevision: 2 });
});

test('unfinished work offers Reconcile and blocks upload while a live lease protects it', async () => {
  const user = userEvent.setup();
  const methods: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (url: string, init?: RequestInit) => {
    if (init?.method) methods.push(`${init.method} ${url.split('/motion-preview')[1]}`);
    if (url.endsWith('/reconcile')) return json({ cleanupPending: false });
    return json(status({ pending: { status: 'failed', outcomeUnknown: true, leaseActive: false } }));
  }));
  mount();

  expect(await screen.findByText('An earlier upload or cleanup needs attention. Reconcile can resolve it.')).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByText('Unfinished preview work was reconciled.')).toBeInTheDocument();
  expect(methods).toEqual(['POST /reconcile']);
  cleanup();

  vi.stubGlobal('fetch', vi.fn(async () => json(status({ pending: { status: 'uploading', outcomeUnknown: true, leaseActive: true } }))));
  mount();
  expect(await screen.findByRole('button', { name: 'Upload preview' })).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Reconcile' })).toBeDisabled();
});

test('a preview made for an earlier Video offers Reconcile, which retires it', async () => {
  const user = userEvent.setup();
  const methods: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (url: string, init?: RequestInit) => {
    if (init?.method) methods.push(`${init.method} ${url.split('/motion-preview')[1]}`);
    if (url.endsWith('/reconcile')) return json({ cleanupPending: false });
    return json(status({ active: active(false) }));
  }));
  mount();

  expect(await screen.findByText(/made for an earlier Video and stays hidden/)).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByText('Unfinished preview work was reconciled.')).toBeInTheDocument();
  expect(methods).toEqual(['POST /reconcile']);
});
